/*
 * verify_js_decoder.mjs — proves the browser decoder in script.js agrees with
 * the Python encoder.
 *
 *   node verify_js_decoder.mjs
 *
 * Vectors below were generated by the Python side (simple_encode.extract and
 * payload_codec.compress_to_bits), so this checks against the real codec rather
 * than against another JavaScript implementation of the same idea.
 *
 * script.js is a classic browser script, not a module, so it is loaded here the
 * way the page loads it: unishox2.js first, then script.js, sharing one global
 * scope, with a stub DOM so the page wiring does not throw.
 */
